using System;
using System.Collections.Generic;
using UnityEngine;

namespace SHHH.Game
{
    /// <summary>Generated by Editor/ShhhAssetPipeline: maps art keys to imported model assets and shared materials.</summary>
    [CreateAssetMenu(menuName = "SHHH/Art Catalog")]
    public sealed class ArtCatalog : ScriptableObject
    {
        [Serializable] public sealed class Entry { public string key; public GameObject model; }
        [Serializable] public sealed class ClipEntry { public string key; public AnimationClip clip; }

        public List<Entry> models = new List<Entry>();
        public Material toonBase;         // SHHH/Toon stylized cel shading (preferred for all opaque lit surfaces)
        public Material litBase;          // URP Lit opaque (procedural furniture, walls)
        public Material unlitBase;        // URP Unlit opaque (emissive bits, text backers)
        public Material unlitTransparent; // URP Unlit transparent (ripples, glows) — used sparingly for Quest 2
        public Material handMaterial;
        public Texture2D logo;
        public Texture2D logoIcon;
        public UnityEngine.Object brandFont;   // TMP_FontAsset (typed as Object to keep this file TMP-agnostic)
        public RuntimeAnimatorController siblingAnimator;
        public RuntimeAnimatorController momAnimator;

        Dictionary<string, GameObject> _map;
        static ArtCatalog _instance;
        public static ArtCatalog I
        {
            get
            {
                if (_instance == null) _instance = Resources.Load<ArtCatalog>("ArtCatalog");
                if (_instance == null) { _instance = CreateInstance<ArtCatalog>(); Debug.LogWarning("[SHHH] ArtCatalog missing — using procedural fallbacks"); }
                return _instance;
            }
        }

        public GameObject Model(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            if (_map == null) { _map = new Dictionary<string, GameObject>(); foreach (var e in models) if (e.model != null) _map[e.key] = e.model; }
            return _map.TryGetValue(key, out var g) ? g : null;
        }
    }
}
